// East Asian typography does not insert spaces between a standalone Latin
// abbreviation and adjacent CJK text (for example: "透明AI网关"). Applying
// the convention here also keeps future translations consistent.
const eastAsianLocales = ["zh-CN", "zh-TW", "ja", "ko"] as const;
const eastAsianCharacter = "[\\p{Script=Han}\\p{Script=Hiragana}\\p{Script=Katakana}\\p{Script=Hangul}]";
const spaceBeforeAI = new RegExp(`(${eastAsianCharacter})\\s+AI\\b`, "gu");
const spaceAfterAI = new RegExp(`\\bAI\\s+(${eastAsianCharacter})`, "gu");
for (const locale of eastAsianLocales) {
  for (const key of Object.keys(translations[locale]) as MessageKey[]) {
    const value = translations[locale][key];
    if (value) translations[locale][key] = value.replace(spaceBeforeAI, "$1AI").replace(spaceAfterAI, "AI$1");
  }
}

const translationGaps = (Object.keys(translations) as Array<Exclude<Locale, "en">>).flatMap((locale) =>
  (Object.keys(en) as MessageKey[]).filter((key) => !translations[locale][key]).map((key) => `${locale}:${key}`)
);
if (translationGaps.length) throw new Error(`Missing translations: ${translationGaps.join(", ")}`);

function detectLocale(): Locale {
  const saved = localStorage.getItem("openswiftscale_locale") as Locale | null;
  if (saved && localeOptions.some((option) => option.value === saved)) return saved;
  const language = navigator.language;
  if (language.toLowerCase() === "zh-tw" || language.toLowerCase() === "zh-hk") return "zh-TW";
  if (language.toLowerCase().startsWith("zh")) return "zh-CN";
  const short = language.split("-")[0] as Locale;
  return localeOptions.some((option) => option.value === short) ? short : "en";
}

interface I18nValue {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: MessageKey) => string;
  formatNumber: (value: number) => string;
  formatDate: (value: string | number | Date) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(detectLocale);
  const setLocale = (next: Locale) => { localStorage.setItem("openswiftscale_locale", next); setLocaleState(next); };
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const value = useMemo<I18nValue>(() => ({
    locale,
    setLocale,
    t: (key) => locale === "en" ? en[key] : translations[locale][key] || en[key],
    formatNumber: (value) => new Intl.NumberFormat(locale).format(value || 0),
    formatDate: (value) => new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "medium" }).format(new Date(value))
  }), [locale]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useI18n must be used inside I18nProvider");
  return value;
}
